	ReasonDuplicate      = "duplicate"
	ReasonCouldNotVerify = "could-not-verify"
)

// Premise and claim verdicts. NoClaims is valid for the premise only.
const (
	Holds      = "holds"
	Fails      = "fails"
	Unresolved = "unresolved"
	NoClaims   = "no-claims"
)

